void __stdcall LoadingsScreen() {
    char szPath[260];
    char* _Format;
    char* pszBaseDir;
    CleanupAfterLoadingAct();
    PALETTE_LoadLoadingScreenPalette();
    uint32_t nLangCode = D2Lang::StrTable::strtable::MISC_GetLanguageCode();
    if (!nLangCode) {
      pszBaseDir = "DATA\\GLOBAL";
      _Format = "%s\\UI\\Loading\\Loadingscreen";
    } else {
      pszBaseDir = "DATA\\LOCAL";
      _Format = "%s\\UI\\LoadingScreen";
    }

    sprintf(szPath, _Format, pszBaseDir);
    gnLoadedActIndex = Core::Archive::IMAGE_LoadDC6Ex(szPath, 0);
    gnLoadScreenAnimFrame = 0;
    gnLastOpenPanelId = 1;
    GAME::Msg::LOADING_SetProgressRatio(0, 0);
    gbLoadScreenLevelLoadInProgress = gLevelLoadInProgress;
}

void __fastcall Draw_UI_LoadGame(int32_t bAdvanceFrame) {
    // Static local variables (originally global data)
    static uint8_t gbLoadBarColorInitialized;
    static uint8_t gbLoadBarOutlineColor;

    int nSizeX;
    D2GfxDataStrc sLoadGfx;
    int32_t nResult = D2gfx::D2GFX::D2GFX_EndCutSceneReturnSceneState();
    if (!nResult) {
      D2gfx::D2GFX::D2GFX_ClearScreen(0);
    }

    eD2GSGameType eGameType = GAME::Game::CLIENT_GetD2GSGameType();
    GAME::Game::GAMEDATA_SendPeriodicPing();
    nResult = D2gfx::D2GFX::D2GFX_EndCutSceneReturnSceneState();
    if (!nResult) {
      BOOL bSceneBegun;
      D2Win::Src::D2WinPalette::DRAW_SetOrReloadPalleteMain();
      bSceneBegun = D2gfx::D2GFX::D2GFX_BeginScene(1, 0, 0, 0);
      if (bSceneBegun) {
        if (!gnLoadedActIndex) {
          LoadingsScreen();
          if (!gnLoadedActIndex) {
            Fog::Src::ErrorManager::ERROR_UnrecoverableInternalError_Halt("", Fog::Src::ErrorManager::GetInstructionPointer(), 0x19c2);
            exit(-1);
          }
        }
        if (eGameType == GAMETYPE_OBNET_HOST || eGameType == GAMETYPE_LAN_HOST || eGameType == GAMETYPE_OBNET_JOIN || eGameType == GAMETYPE_LAN_JOIN) {
          if (!gbLoadBarColorInitialized) {
            nResult = D2Win::Src::D2WinPalette::D2GFX_GetColorFromCurrentPallete(0x60, 0, 0);
            gbLoadBarColorInitialized = (uint8_t)nResult;
            nResult = D2Win::Src::D2WinPalette::D2GFX_GetColorFromCurrentPallete(0xff, 0xff, 0);
            gbLoadBarOutlineColor = (uint8_t)nResult;
          }
          if (!gbLoadScreenLevelLoadInProgress) {
            D2gfx::D2GFX::D2GFX_DrawSolidRectEx(ScreenSizeX / 2 - 0x82, ScreenSizeY / 2 + 0x9e, ScreenSizeX / 2 + 0x82, ScreenSizeY / 2 + 0xb2, (uint32_t)gbLoadBarOutlineColor, DRAW_TRANSPARENT);
            D2gfx::D2GFX::D2GFX_DrawSolidRectEx(ScreenSizeX / 2 - 0x80, ScreenSizeY / 2 + 0xa0, ScreenSizeX / 2 + 0x80, ScreenSizeY / 2 + 0xb0, 0, DRAW_SOLID);
            nSizeX = GAME::Msg::LOADING_GetProgressRatio();
            if (nSizeX) {
              Engine::GfxInfo::D2GFX_DrawSolidRectExBySize(ScreenSizeX / 2 - 0x80, ScreenSizeY / 2 + 0xa0, nSizeX, 0x10, (uint32_t)gbLoadBarColorInitialized, DRAW_SOLID);
            }
          }
        }

        nResult = D2CMP::SRC::CelCmp::IMAGE_GetFramesCount(gnLoadedActIndex);
        if (nResult <= gnLoadScreenAnimFrame) {
          gnLoadScreenAnimFrame = nResult - 1;
        }

        sLoadGfx.pDC6 = gnLoadedActIndex;
        sLoadGfx.nDirection = 0;
        sLoadGfx.nFrameNumber = gnLoadScreenAnimFrame;
        D2gfx::D2GFX::D2GFX_DrawImage(&sLoadGfx, ScreenSizeX / 2 - 0x80, ScreenSizeY / 2 + 0x80, -1, DRAW_SOLID, nullptr);
        D2gfx::D2GFX::D2GFX_EndScene();
        GAME::Game::UI_ResetInputState();
        GAME::Game::GAMEDATA_ClearQueuedClicks();
      }
    }
    if (!bAdvanceFrame) {
      return;
    }

    gnLoadScreenAnimFrame++;
}

